Here's a complete, well-structured C++ program for calculating trapezoid area:

```cpp
#include <iostream>
#include <iomanip>

using namespace std;

int main() {
    // Variable declarations
    double longerBase, shorterBase, height;
    double area;

    // Clear screen (optional, works on most terminals)
    cout << "\t=== Trapezoid Area Calculator ===\n\n";

    // Prompt for longer base
    cout << "Enter the measurement of the longer base of the trapezoid: ";
    cin >> longerBase;

    // Validate input
    while (longerBase <= 0) {
        cout << "Error: Base measurements must be positive numbers.\n";
        cout << "Enter the measurement of the longer base of the trapezoid: ";
        cin >> longerBase;
    }

    // Prompt for shorter base
    cout << "\nEnter the measurement of the shorter base of the trapezoid: ";
    cin >> shorterBase;

    // Validate input
    while (shorterBase <= 0) {
        cout << "Error: Base measurements must be positive numbers.\n";
        cout << "Enter the measurement of the shorter base of the trapezoid: ";
        cin >> shorterBase;
    }

    // Prompt for height
    cout << "\nEnter the height of the trapezoid: ";
    cin >> height;

    // Validate input
    while (height <= 0) {
        cout << "Error: Height must be a positive number.\n";
        cout << "Enter the height of the trapezoid: ";
        cin >> height;
    }

    // Calculate area
    area = 0.5 * (longerBase + shorterBase) * height;

    // Display results in user-friendly format
    cout << "\n\t=== Your Trapezoid Information ===\n\n";
    cout << left << setw(15) << "Trapezoid Details:" << endl;
    cout << setw(15) << "Longer Base: " << fixed << longerBase << endl;
    cout << setw(15) << "Shorter Base: " << shorterBase << endl;
    cout << setw(15) << "Height: " << height << endl;
    cout << "\nCalculated Area: " << fixed << setprecision(2) << area << endl;

    // Approval message
    cout << "\n*Area calculation complete!*";

    return 0;
}
```

This program includes:
- Input validation to prevent invalid calculations
- Clear, formatted output with labels
- Decimal precision for the area calculation
- User-friendly prompts and error messages

The area formula used is: **Area = (Longer Base + Shorter Base) × Height ÷ 2**

